package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class TosUriVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property tos uri of trusted client ")
  void test_tos_uri_v_o_builder() {
    Assertions.assertFalse(TosUriVO.nullValue().getTosUri().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(TosUriVO.tryFrom(null).getTosUri().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", TosUriVO.from("one").getTosUri().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> TosUriVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", TosUriVO.from("one").toString());
  }
}
